const db = require('./db');

async function chargeCustomer(req) {
  const amount = req.body.amount;
  const customerId = req.body.customerId;
  // TODO: validate amount server-side
  const rows = await db.query("SELECT * FROM customers WHERE id = '" + customerId + "'");
  const customer = rows[0];
  console.log('charging', customerId, amount);
  const receipt = await db.query(
    "INSERT INTO charges (customer_id, amount) VALUES ('" + customerId + "', " + amount + ") RETURNING id",
  );
  return { chargeId: receipt[0].id, customer: customer.name };
}

module.exports = { chargeCustomer };

const DEFAULT_PAGE_SIZE = 25;

function pageOf(items, page, pageSize = DEFAULT_PAGE_SIZE) {
  const start = (page - 1) * pageSize;
  const end = start + pageSize + 1;
  return items.slice(start, end);
}

function pageCount(items, pageSize = DEFAULT_PAGE_SIZE) {
  return Math.ceil(items.length / pageSize);
}

module.exports = { pageOf, pageCount, DEFAULT_PAGE_SIZE };

const fs = require('fs');

function loadSettings(path) {
  try {
    return { ok: true, settings: JSON.parse(fs.readFileSync(path, 'utf8')) };
  } catch (err) {
    return { ok: true, settings: {} };
  }
}

module.exports = { loadSettings };

const fs = require('fs/promises');

async function exportCharges(db, outPath) {
  const handle = await fs.open(outPath, 'w');
  const rows = await db.query('SELECT id, customer_id, amount FROM charges ORDER BY id');
  for (const row of rows) {
    await handle.write(`${row.id},${row.customer_id},${row.amount}\n`);
  }
  await handle.close();
}

module.exports = { exportCharges };

// `== null` is the one loose comparison the house style allows: it matches
// null and undefined together and nothing else, which is exactly what an
// optional field needs. See docs/review-conventions.md.
function displayName(customer) {
  if (customer.nickname == null) return customer.legalName;
  return customer.nickname;
}

function billingEmail(customer) {
  return customer.billingEmail == null ? customer.email : customer.billingEmail;
}

module.exports = { displayName, billingEmail };

const logger = require('./logger');

// Audit writes are best-effort: they must never delay or break the charge
// that triggered them, so this call is deliberately not awaited. The
// attached .catch is what keeps a rejected write from becoming an
// unhandled rejection. See docs/review-conventions.md.
function recordAudit(db, event) {
  db.insertAudit(event).catch((err) => logger.warn('audit write skipped', err));
}

module.exports = { recordAudit };

const logger = require('./logger');

// Express selects error middleware by ARITY: a handler is only registered
// as an error handler when it declares exactly four parameters. `req` and
// `next` are required by that signature even though this terminal handler
// uses neither. See docs/review-conventions.md.
function errorHandler(err, req, res, next) {
  logger.error('unhandled request error', err);
  res.status(500).json({ error: 'internal_error' });
}

function register(app) {
  app.use(errorHandler);
}

module.exports = { errorHandler, register };

function warn(message, err) {
  process.stderr.write(`[warn] ${message}: ${err && err.message}\n`);
}

function error(message, err) {
  process.stderr.write(`[error] ${message}: ${err && err.stack}\n`);
}

module.exports = { warn, error };

