// Precision/recall oracle for the snapshot code review.
//
// Run by the harness with the reviewed workspace as cwd. It grades the two
// halves of a real review separately, because recall alone is passed by a
// review that flags everything:
//
//   RECALL    - each of the four seeded defects in the change set is
//               reported, against the right file and as the right class.
//   PRECISION - no finding repeats one of the three shotgun smells the
//               change set deliberately baits, and no finding is raised
//               against a file outside the change set.
//
// Two rules keep this from punishing correct work.
//
// First, defect classes are matched by the ordinary vocabulary of the
// class, never by wording this fixture invented: "26 items per page",
// "the end index is one too high" and "half-open range" all count as the
// pagination defect. The bar is "a real review of this class", not this
// scenario's phrasing.
//
// Second, the precision half is scoped to the SMELL, not to the file.
// src/customer.js, src/audit.js and src/errors.js are baited with a
// documented house-style construct that must not be flagged - but they
// are still ordinary code, and a reviewer may legitimately find
// something else in them (a missing res.headersSent guard in the error
// handler, say, or a synchronous throw escaping the best-effort audit
// call). Failing those would punish the exact deep reading this eval is
// trying to reward, so only a finding that IS the baited smell counts
// against precision. Whole-file scope is reserved for the two files that
// are not in the change set at all, where any finding is out of scope by
// the book's own rule.
//
// Precision is graded on the finding records only: a report that
// discusses a correct construct and explicitly clears it is good
// reviewing, and is not penalised here.
import { readFileSync } from 'node:fs';

/**
 * Fail with the message ALONE on stderr.
 *
 * A thrown Error would work, but the harness feeds this script's stderr
 * into the model's repair nudge verbatim, and an uncaught throw pads that
 * nudge with a Node stack trace and a version banner. The actionable
 * sentence is what the next attempt needs; the stack is noise that pushes
 * it out of view on a small model.
 */
function fail(message) {
  console.error(message);
  process.exit(1);
}


const FINDINGS = 'review-output/findings.json';

let raw;
try {
  raw = readFileSync(FINDINGS, 'utf8');
} catch {
  fail(FINDINGS + ' does not exist - the machine-readable finding list is required');
}

let findings;
try {
  findings = JSON.parse(raw.replace(/^\uFEFF/, ''));
} catch (err) {
  fail(FINDINGS + ' is not valid JSON: ' + err.message);
}
if (!Array.isArray(findings)) {
  const nested =
    findings && typeof findings === 'object'
      ? Object.values(findings).find((value) => Array.isArray(value))
      : null;
  if (!nested) fail(FINDINGS + ' must be an array of finding records');
  findings = nested;
}
findings = findings.filter((finding) => finding && typeof finding === 'object');

// Every PROSE string anywhere in the record, nested objects and arrays
// included - a reviewer who nests the explanation under `detail` or
// splits it across an array is saying the same thing. Citation and
// identifier fields are excluded: they are addresses, not description,
// and letting them through means a line number or a path fragment can
// satisfy a defect-class matcher by coincidence.
const CITATION_KEYS = new Set([
  'file',
  'path',
  'filename',
  'location',
  'line',
  'lines',
  'endline',
  'startline',
  'column',
  'col',
  'id',
  '#',
]);
const collectStrings = (value, out) => {
  if (typeof value === 'string') out.push(value);
  else if (Array.isArray(value)) for (const item of value) collectStrings(item, out);
  else if (value && typeof value === 'object') {
    for (const [key, item] of Object.entries(value)) {
      if (CITATION_KEYS.has(key.toLowerCase())) continue;
      collectStrings(item, out);
    }
  }
  return out;
};
const text = (finding) => collectStrings(finding, []).join(' ').toLowerCase();

const fileOf = (finding) =>
  String(finding.file ?? finding.path ?? finding.filename ?? finding.location ?? '')
    .replace(/\\/g, '/')
    .replace(/^\.\//, '')
    .replace(/^[ab]\//, '')
    .replace(/\s*\([^()]*\)\s*$/, '')
    .replace(/[:#]\s*L?\d+(?:\s*-\s*L?\d+)?\s*$/, '')
    .trim();

// Basenames are unique across every seeded file, so a bare `payment.js`
// citation resolves the same as `src/payment.js`.
const onFile = (path) => {
  const base = path.slice(path.lastIndexOf('/') + 1);
  const full = new RegExp('(^|/)' + path.replace(/\./g, '\\.') + '$');
  const bare = new RegExp('^' + base.replace(/\./g, '\\.') + '$');
  return findings.filter((finding) => {
    const cited = fileOf(finding);
    return full.test(cited) || bare.test(cited);
  });
};

const REQUIRED = [
  {
    file: 'src/payment.js',
    label: 'the customer and charge queries build SQL by string concatenation from req.body',
    match: (t) =>
      /injection|sqli\b|parameteri|parametri|placeholder|prepared statement|\bbind\b|\bbinding\b|bound parameter|concatenat|interpolat|escap|sanitiz|quoting/.test(
        t,
      ) ||
      (/\bsql\b|\bquery\b|\bqueries\b|statement/.test(t) &&
        /untrusted|user[- ](?:input|supplied|controlled|data)|req\.body|request (?:value|data|input|body)|unsafe|unsanitiz|unvalidated|string (?:concat|building|built)|built from|splic/.test(
          t,
        )),
  },
  {
    file: 'src/pagination.js',
    label: 'pageOf is off by one on its slice end bound, so pages overlap by a row',
    match: (t) =>
      /off.?by.?one|\bslice\b|\bbound(?:ary|aries|s)?\b|half.?open|exclusive|inclusive|overlap|duplicat|repeat|reappear|one too many|one (?:extra|more)|too many|extra (?:item|row|record|element|entry|result)|\+\s?1\b|pagesize \+|\+ pagesize|increment|\b26\b|end (?:index|bound|offset|position)|last (?:item|row|record|element)/.test(
        t,
      ),
  },
  {
    file: 'src/settings.js',
    label: 'loadSettings swallows the parse error and still reports ok: true',
    match: (t) =>
      /swallow|silent|suppress|\bmask|\bhid(?:e|es|den|ing)|\bignor|empty catch|catch block|\bok\b|\btrue\b|success|succeed|re-?throw|rethrow|propagat|bubble|surfac|indistinguishable|no indication|cannot tell|unaware|misleading|misreport|false (?:success|positive)|as if|pretend/.test(
        t,
      ),
  },
  {
    file: 'src/export.js',
    label: 'exportCharges leaks the file handle when the query or a write throws',
    match: (t) =>
      /leak|\bclos(?:e|es|ed|ing)\b|\bfinally\b|clean.?up|releas|dispos|\bhandle\b|descriptor|\bfd\b|resource|left open|remains open|stays open|still open|dangling|exhaust|unclosed/.test(
        t,
      ),
  },
];

const missing = REQUIRED.filter(
  (required) => !onFile(required.file).some((finding) => required.match(text(finding))),
);
if (missing.length > 0) {
  const reported = findings.map((finding) => fileOf(finding) || '?').join(', ') || '(nothing)';
  fail(
    'RECALL SHORTFALL - the change set holds four separate defects and these were not reported: ' +
      missing.map((entry) => entry.file + ' (' + entry.label + ')').join('; ') +
      '. Files carrying a reported finding: ' +
      reported +
      '. Re-walk changes.diff hunk by hunk; every defect above is visible in the added lines.',
  );
}

// Baited smells. Each of these three files carries a construct that looks
// like a common lint smell and is documented house style in
// docs/review-conventions.md. Only a finding that raises THAT construct
// is a precision failure; any other observation about the file is fair
// review work and passes.
const BAITED = [
  {
    file: 'src/customer.js',
    smell: 'loose equality',
    matches: (t) =>
      /[=!]==?|loose equal|strict equal|\bequality\b|double equals|triple equals|coerc|nullish|\?\?/.test(
        t,
      ),
    why: '`== null` is the documented house idiom for a null-or-undefined check (docs/review-conventions.md) and is not to be tightened',
  },
  {
    file: 'src/audit.js',
    smell: 'floating / unawaited promise',
    matches: (t) =>
      /floating|un-?awaited|not awaited|missing await|no await|without await|should (?:be )?await|add (?:an )?await|\bawait\b|fire.?and.?forget|dangling promise|unhandled (?:promise )?rejection/.test(
        t,
      ) &&
      // A reviewer who spots that a SYNCHRONOUS throw from insertAudit
      // still escapes into the charge path has found something real, not
      // the bait. That finding is welcome.
      !/synchronous|synchronously|thenable|non-?promise|not (?:return )?a promise|does not return|returns undefined|before the promise/.test(
        t,
      ),
    why: 'the audit write is deliberately not awaited and carries a .catch, which is the required form for a best-effort write (docs/review-conventions.md)',
  },
  {
    file: 'src/errors.js',
    smell: 'unused parameters',
    matches: (t) =>
      /unused|not used|never used|un-?referenced|no-unused-vars|underscore|_req|_next|dead (?:parameter|argument)|(?:remove|drop|omit) (?:the )?(?:`?req`?|`?next`?|parameter|argument)|unnecessary (?:parameter|argument)/.test(
        t,
      ),
    why: "Express registers error middleware by arity, so the four-parameter signature and the parameters it does not use are required (docs/review-conventions.md)",
  },
];

// Not in manifest.json's seven-file list and not in changes.diff. The
// book says to discuss only files in the change set, so any finding here
// is out of scope whatever it says.
const OUT_OF_SCOPE = [
  { file: 'src/util.js', why: 'it is not one of the seven files in manifest.json' },
  { file: 'src/logger.js', why: 'it is not one of the seven files in manifest.json' },
];

const nameOf = (finding) =>
  String(finding.category ?? finding.finding ?? finding.title ?? 'unnamed');

const wrong = [];
for (const bait of BAITED) {
  for (const finding of onFile(bait.file)) {
    if (!bait.matches(text(finding))) continue;
    wrong.push(bait.file + ' (' + nameOf(finding) + ' - ' + bait.smell + ') - ' + bait.why);
  }
}
for (const out of OUT_OF_SCOPE) {
  for (const finding of onFile(out.file)) {
    wrong.push(out.file + ' (' + nameOf(finding) + ') - ' + out.why);
  }
}
if (wrong.length > 0) {
  fail(
    'PRECISION SHORTFALL - drop these records from ' +
      FINDINGS +
      ': ' +
      wrong.join('; ') +
      '. A review that raises everything is not usable. Re-read docs/review-conventions.md, ' +
      'which names the shapes that are deliberate house style, and re-read manifest.json for ' +
      'which files are actually under review. Discussing a construct in report.md and clearing ' +
      'it is fine - listing it as a finding is not. Any OTHER defect you find in these files is ' +
      'welcome; only the constructs named above are off limits.',
  );
}

console.log(
  'CODEREVIEW_ORACLE ok - all 4 seeded defects reported (src/payment.js, src/pagination.js, ' +
    'src/settings.js, src/export.js) and none of the 3 baited house-style smells or 2 ' +
    'out-of-scope files carries a finding.',
);
